y.x:
var $bm_rt;
var ctrl, linesShown, baseY, lineOffset;
ctrl = thisComp.layer('Line Control');
linesShown = ctrl.effect('Number of Lines in Headline')('Menu').value;
baseY = 900;
lineOffset = -75;
$bm_rt = $bm_sum(baseY, $bm_mul($bm_sub(linesShown, 1), lineOffset));

o.x:
var $bm_rt;
var ctrl, linesShown;
ctrl = thisComp.layer('Line Control');
linesShown = ctrl.effect('Number of Lines in Headline')('Menu').value;
$bm_rt = $bm_mul(value, linesShown >= 2 ? 1 : 0);

var $bm_rt;
var ctrl, linesShown;
ctrl = thisComp.layer('Line Control');
linesShown = ctrl.effect('Number of Lines in Headline')('Menu').value;
$bm_rt = $bm_mul(value, linesShown >= 3 ? 1 : 0);

p.x:
var $bm_rt;
var ctrl, linesShown, linesOff, gap;
ctrl = thisComp.layer('Line Control');
linesShown = ctrl.effect('Number of Lines in Headline')('Menu').value;
linesOff = $bm_sub(3, linesShown);
gap = 90;
$bm_rt = $bm_sub(value, [
    0,
    gap * linesOff
]);

var $bm_rt;
var gapBelow, breakLineY;
gapBelow = 380;
breakLineY = thisComp.layer('breaking line').transform.position[1];
$bm_rt = [
    value[0],
    breakLineY + gapBelow
];
